/**
 * Mahjong Classic rules engine — pure functions, no React.
 *
 * Coordinates are in half-tile units: a tile at (x, y, z) covers the cells
 * x..x+1, y..y+1 on layer z, so half-offset tiles (the turtle's cap) work.
 * A tile is FREE when no tile on a higher layer overlaps it and at least one
 * horizontal side (left or right, same layer) is open.
 *
 * Boards are generated by reverse removal: pairs of positions that are free
 * in the (shrinking) layout are taken out one by one, and each pair gets one
 * matching face pair. Playing that removal order forward always clears the
 * board, so every deal is solvable by construction. Shuffle re-runs the same
 * construction on the tiles that remain.
 */

/* ---------- layouts ---------- */

// rect/row take tile units (halves allowed) and emit half-unit [x, y, z] cells
const rect = (out, z, x0, y0, w, h) => {
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) out.push([(x0 + x) * 2, (y0 + y) * 2, z]);
  return out;
};
const row = (out, z, y, x0, n) => rect(out, z, x0, y, n, 1);

function turtle() {
  const t = [];
  [[1, 12], [3, 8], [2, 10], [1, 12], [1, 12], [2, 10], [3, 8], [1, 12]].forEach(([x0, n], y) => row(t, 0, y, x0, n));
  t.push([0, 7, 0], [26, 7, 0], [28, 7, 0]);
  rect(t, 1, 4, 1, 6, 6);
  rect(t, 2, 5, 2, 4, 4);
  rect(t, 3, 6, 3, 2, 2);
  t.push([13, 7, 4]);
  return t;
}
function pyramid() {
  const t = rect([], 0, 0, 0, 10, 6);
  rect(t, 1, 1, 1, 8, 4);
  rect(t, 2, 2, 2, 6, 2);
  row(t, 3, 2.5, 3, 4);
  return t;
}
function bridge() {
  const t = rect([], 0, 0, 0, 3, 6);
  rect(t, 0, 11, 0, 3, 6);
  rect(t, 0, 3, 2, 8, 2);
  rect(t, 1, 1, 1, 2, 4);
  rect(t, 1, 11, 1, 2, 4);
  rect(t, 1, 3, 2, 8, 2);
  row(t, 2, 2.5, 4, 6);
  rect(t, 2, 1, 2, 2, 2);
  rect(t, 2, 11, 2, 2, 2);
  return t;
}
function fortress() {
  const t = [];
  row(t, 0, 0, 0, 12);
  row(t, 0, 7, 0, 12);
  for (let y = 1; y < 7; y++) t.push([0, y * 2, 0], [22, y * 2, 0]);
  t.push([2, 2, 0], [20, 2, 0], [2, 12, 0], [20, 12, 0]);
  rect(t, 0, 4, 3, 4, 2);
  for (const [x, y] of [[0, 0], [10, 0], [0, 6], [10, 6]]) rect(t, 1, x, y, 2, 2);
  rect(t, 1, 4, 3, 4, 2);
  for (const [x, y] of [[0.5, 0.5], [10.5, 0.5], [0.5, 6.5], [10.5, 6.5]]) t.push([x * 2, y * 2, 2]);
  row(t, 2, 3.5, 5, 2);
  return t;
}
function compact() {
  const t = rect([], 0, 0, 0, 8, 5);
  rect(t, 1, 1, 1, 6, 3);
  row(t, 2, 2, 2, 4);
  return t;
}

export const LAYOUTS = {
  turtle: { label: "Classic Turtle", cells: turtle() },
  pyramid: { label: "Pyramid", cells: pyramid() },
  bridge: { label: "Bridge", cells: bridge() },
  fortress: { label: "Fortress", cells: fortress() },
  compact: { label: "Compact", cells: compact() },
};

/** perKind: tiles per face family (more copies = more matches on offer); hints: per game (Infinity = unlimited) */
export const DIFFICULTIES = {
  easy: { label: "Easy", perKind: 8, hints: Infinity, mult: 1 },
  medium: { label: "Medium", perKind: 4, hints: 6, mult: 1.5 },
  hard: { label: "Hard", perKind: 2, hints: 3, mult: 2 },
};

/* ---------- faces ---------- */

// 36 match families: dots / bamboo / symbols 1-9, four winds, three dragons, flowers, seasons.
// Flowers (f1-f4) match any flower, seasons (x1-x4) any season.
export const FAMILIES = [
  ..."dbs".split("").flatMap((s) => [1, 2, 3, 4, 5, 6, 7, 8, 9].map((n) => s + n)),
  "wE", "wS", "wW", "wN", "rR", "rG", "rW", "f", "x",
];
export const matchKey = (face) => (face[0] === "f" || face[0] === "x" ? face[0] : face);
export const canMatch = (a, b) => matchKey(a) === matchKey(b);

/* ---------- geometry ---------- */

const overlaps = (a, b) => Math.abs(a.x - b.x) < 2 && Math.abs(a.y - b.y) < 2;

/** For each tile index: { above: [idx], left: [idx], right: [idx] } */
export function neighbours(cells) {
  return cells.map((a, i) => {
    const n = { z: a.z, above: [], left: [], right: [] };
    cells.forEach((b, j) => {
      if (i === j || Math.abs(a.y - b.y) >= 2) return;
      if (b.z > a.z && overlaps(a, b)) n.above.push(j);
      else if (b.z === a.z && b.x === a.x - 2) n.left.push(j);
      else if (b.z === a.z && b.x === a.x + 2) n.right.push(j);
    });
    return n;
  });
}

/** Is tile i free, given `alive(j)` for the tiles still on the board? */
export function isFree(nb, i, alive) {
  const n = nb[i];
  if (n.above.some(alive)) return false;
  return !n.left.some(alive) || !n.right.some(alive);
}

const shuffled = (arr, rnd) => {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

/**
 * Reverse removal over the tile indices in `live`: returns a list of index
 * pairs that, removed in order, empties the board — or null if the random
 * walk got stuck (call again; `tries` attempts are made). Higher tiles are
 * preferred so stacks get unpicked before the floor runs out of free tiles.
 */
export function removalOrder(nb, live, rnd = Math.random, tries = 80) {
  for (let attempt = 0; attempt < tries; attempt++) {
    const on = new Set(live);
    const alive = (j) => on.has(j);
    const order = [];
    while (on.size) {
      const free = [...on].filter((i) => isFree(nb, i, alive));
      if (free.length < 2) break;
      const pick = () => {
        let total = 0;
        const w = free.map((i) => (total += 1 + nb[i].z * 1.5));
        const r = rnd() * total;
        const k = w.findIndex((v) => v >= r);
        return free.splice(k < 0 ? 0 : k, 1)[0];
      };
      const a = pick();
      const b = pick();
      order.push([a, b]);
      on.delete(a);
      on.delete(b);
    }
    if (!on.size) return order;
  }
  return null;
}

/** Face pairs for `pairs` matches at a difficulty: [["d3","d3"], ["f1","f2"], ...] */
function deck(pairs, perKind, rnd) {
  const out = [];
  const bonus = { f: ["f1", "f2", "f3", "f4"], x: ["x1", "x2", "x3", "x4"] };
  while (out.length < pairs) {
    for (const fam of shuffled(FAMILIES, rnd)) {
      for (let k = 0; k < perKind / 2 && out.length < pairs; k++) {
        if (bonus[fam]) {
          const b = shuffled(bonus[fam], rnd);
          out.push([b[0], b[1]]);
        } else out.push([fam, fam]);
      }
      if (out.length >= pairs) break;
    }
  }
  return shuffled(out, rnd);
}

/* ---------- game state ---------- */

/**
 * State: { layout, level, tiles: [{x,y,z}], nb, faces: [face], gone: [bool],
 *          moves, score, combo, lastMatch, hints, shuffles, history: [snapshot],
 *          since, elapsed, paused, won, seed key }
 */
export function newGame(layout = "turtle", level = "medium", rnd = Math.random) {
  const tiles = LAYOUTS[layout].cells.map(([x, y, z]) => ({ x, y, z }));
  const nb = neighbours(tiles);
  let order = null;
  while (!order) order = removalOrder(nb, tiles.map((_, i) => i), rnd, 200);
  const faces = new Array(tiles.length);
  const pairs = deck(order.length, DIFFICULTIES[level].perKind, rnd);
  order.forEach(([a, b], k) => ((faces[a] = pairs[k][0]), (faces[b] = pairs[k][1])));
  return {
    layout, level, tiles, nb, faces, gone: tiles.map(() => false), solution: order,
    moves: 0, score: 0, combo: 0, lastMatch: 0, hintsUsed: 0, shuffles: 0, history: [],
    since: null, elapsed: 0, paused: false, won: false, key: Math.random(),
  };
}

export const remaining = (s) => s.gone.reduce((n, g) => n + (g ? 0 : 1), 0);
export const freeTile = (s, i) => !s.gone[i] && isFree(s.nb, i, (j) => !s.gone[j]);

/** All legal matching pairs [[i, j], ...] on the current board. */
export function availablePairs(s) {
  const byKey = {};
  s.tiles.forEach((_, i) => freeTile(s, i) && (byKey[matchKey(s.faces[i])] ||= []).push(i));
  const out = [];
  for (const list of Object.values(byKey)) for (let a = 0; a < list.length; a++) for (let b = a + 1; b < list.length; b++) out.push([list[a], list[b]]);
  return out;
}

/** A legal hint, preferring the next pair of the known solution when it is still playable. */
export function hint(s) {
  const pairs = availablePairs(s);
  if (!pairs.length) return null;
  const next = s.solution?.find(([a, b]) => !s.gone[a] && !s.gone[b]);
  if (next && freeTile(s, next[0]) && freeTile(s, next[1]) && canMatch(s.faces[next[0]], s.faces[next[1]])) return next;
  return pairs[0];
}

const snap = (s) => ({ faces: s.faces, gone: s.gone, score: s.score, moves: s.moves, combo: s.combo, solution: s.solution });
const clock = (s, now) => (s.since == null ? s : { ...s, elapsed: s.elapsed + (now - s.since), since: now });
export const timeOf = (s, now) => s.elapsed + (s.since != null ? now - s.since : 0);

/** Score for a match at `now` (ms): base 10 x difficulty + quick-match combo bonus (capped at x5). */
function matchScore(s, now) {
  const quick = s.lastMatch && now - s.lastMatch < 4000;
  const combo = quick ? Math.min(5, s.combo + 1) : 0;
  return { gain: Math.round((10 + combo * 5) * DIFFICULTIES[s.level].mult), combo };
}

/** Try to match tiles a and b. Returns the new state, or null if illegal. */
export function match(s, a, b, now = Date.now()) {
  if (a === b || s.won || s.paused || !freeTile(s, a) || !freeTile(s, b) || !canMatch(s.faces[a], s.faces[b])) return null;
  const started = s.since == null ? { ...s, since: now } : s;
  const gone = s.gone.slice();
  gone[a] = gone[b] = true;
  const { gain, combo } = matchScore(s, now);
  let next = { ...started, history: [...s.history, snap(s)], gone, moves: s.moves + 1, score: s.score + gain, combo, lastMatch: now };
  if (!remaining(next)) {
    next = clock(next, now);
    const secs = Math.round(next.elapsed / 1000);
    const bonus = Math.max(0, Math.round((s.tiles.length * 3 - secs) * DIFFICULTIES[s.level].mult));
    next = { ...next, since: null, won: true, score: next.score + bonus, timeBonus: bonus };
  }
  return next;
}

export function undo(s) {
  if (!s.history.length || s.won) return s;
  const prev = s.history[s.history.length - 1];
  return { ...s, ...prev, history: s.history.slice(0, -1), lastMatch: 0, undos: (s.undos || 0) + 1 };
}

/**
 * Reshuffle the faces of the remaining tiles into a solvable arrangement.
 * If the remaining *positions* cannot be cleared in any order (e.g. a lone
 * stack of two), rewind the history to the nearest position that can, then
 * reshuffle there. Returns { state, rewound }.
 */
export function shuffle(s, rnd = Math.random) {
  let base = s;
  let rewound = 0;
  for (;;) {
    const live = base.tiles.map((_, i) => i).filter((i) => !base.gone[i]);
    const order = removalOrder(base.nb, live, rnd, 120);
    if (order) {
      // regroup the remaining faces into matching pairs, then deal them along the order
      const byKey = {};
      live.forEach((i) => (byKey[matchKey(base.faces[i])] ||= []).push(base.faces[i]));
      const pairs = [];
      for (const list of Object.values(byKey)) for (let k = 0; k < list.length; k += 2) pairs.push([list[k], list[k + 1]]);
      const deal = shuffled(pairs, rnd);
      const faces = base.faces.slice();
      order.forEach(([a, b], k) => ((faces[a] = deal[k][0]), (faces[b] = deal[k][1])));
      const penalty = Math.round(20 * DIFFICULTIES[s.level].mult);
      return {
        state: { ...s, ...snap(base), history: [...base.history, snap(base)], faces, solution: order, shuffles: s.shuffles + 1, score: Math.max(0, base.score - penalty), combo: 0, lastMatch: 0 },
        rewound,
      };
    }
    if (!base.history.length) return { state: s, rewound: 0 }; // unreachable: the deal itself is solvable
    base = { ...base, ...base.history[base.history.length - 1], history: base.history.slice(0, -1) };
    rewound++;
  }
}

export function pause(s, now = Date.now()) {
  if (s.paused || s.won) return s;
  return { ...clock(s, now), since: null, paused: true, wasRunning: s.since != null };
}
export function resume(s, now = Date.now()) {
  if (!s.paused) return s;
  return { ...s, paused: false, since: s.wasRunning ? now : null };
}

export const formatTime = (ms) => {
  const t = Math.floor(ms / 1000);
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, "0")}`;
};
